import{_ as n,l as s,o as e,c as i,v as r,p as l,x as t,d,i as T,S as c}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"RTO 与 Karn","description":"","frontmatter":{"title":"RTO 与 Karn","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-rto.md","filePath":"cs/tcp-rto.md","lastUpdated":1789023840000}'),p={name:"cs/tcp-rto.md"};function E(A,a,R,h,_,B){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="rto-与-karn" tabindex="-1">RTO 与 Karn <a class="header-anchor" href="#rto-与-karn" aria-label="Permalink to &quot;RTO 与 Karn&quot;">​</a></h1><div class="epigraph"><p>重传超时必须跟着测量到的往返时间走；一次重传之后的 ACK 不能用来更新估计，否则会把超时越调越乱。</p><footer>—— 据 RFC 793 的超时重传；Karn and Partridge, 1987；Kurose and Ross</footer></div><p><a href="/cs/tcp-seq-rexmit">上一课</a>给出序号、累计 ACK 与「丢了就重发」。本课不重讲滑动前缀。缺口是<strong>何时</strong>重发：超时太短则假重传挤网络，太长则空等。<a href="/cs/tcp-congestion">拥塞控制</a>还没开课，但 RTO 已经会制造重复段。Karn 算法处理「这段是第一次发还是重发的」的歧义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RTT 随路径变。RFC 793 已有重传，工程上用平滑 RTT 与均值偏差（Jacobson）设 RTO。若某段重传过，回来的 ACK 无法对应哪一次发送，把这次样本算进估计会系统性偏低或偏高。Karn：忽略重传段的 RTT 样本，并在重传时指数退避 RTO。缺口是<strong>定时器与估计的一致性</strong>，不是选择确认。</p><p><span class="marginnote">时间戳选项后来让重传段也可测 RTT，那是对 Karn 的补充，不是取消「测不准就别更新」。假超时仍会进入拥塞响应，后课再收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对未重传的段：采样 RTT，更新平滑值与偏差，RTO = 平滑 + 系数×偏差，并设下限。超时：重传最早未确认段，RTO 加倍，直到收到新 ACK 再按测量恢复。快速重传（三重复 ACK）是另一条丢包信号，其定时器交互留给后课 SACK/拥塞。</p>',8)),(e(),l(c,null,{default:t(()=>[T(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAMPLE%5B%22%E6%9C%AA%E9%87%8D%E4%BC%A0%E6%AE%B5%E7%9A%84%20RTT%22%5D%20--%3E%20EST%5B%22%E5%B9%B3%E6%BB%91%E4%B8%8E%E5%81%8F%E5%B7%AE%22%5D%0A%20%20EST%20--%3E%20RTO%5B%22%E9%87%8D%E4%BC%A0%E8%B6%85%E6%97%B6%22%5D%0A%20%20REX%5B%22%E5%B7%B2%E9%87%8D%E4%BC%A0%22%5D%20--%3E%20KARN%5B%22%E4%B8%8D%E9%87%87%E7%94%A8%E8%AF%A5%20ACK%20%E4%BD%9C%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20KARN%20--%3E%20BACK%5B%22RTO%20%E6%8C%87%E6%95%B0%E9%80%80%E9%81%BF%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RTO 把「IP 会丢」翻译成发送方的时钟。估计错误时，<a href="/cs/layering-e2e">端到端</a> 仍最终可靠（重传到对），但延迟与负载变差。Karn 避免正反馈：超时 → 重传 → 错误样本 → 更小 RTO → 更多超时。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Linux 的 min RTO 默认值当 RFC 正文，不引入 F-RTO 全部细节。累计 ACK 仍不能告诉发送方「中间哪块到了」，下一课 SACK。</p><p>后课默认：超时按测量走，重传段不污染 RTT。块状丢失的信息下一课补。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RTO 跟随 RTT；Karn 丢掉有歧义的样本并退避。</li><li>假超时会制造重复段。</li><li>选择确认下一课。</li><li>出处：RFC 793；Karn and Partridge, 1987；Kurose and Ross。</li></ul>',7))])}const u=n(p,[["render",E]]);export{m as __pageData,u as default};
